  `voucher_discount_amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `original_booking_id` int DEFAULT NULL,
  `booking_type` enum('advance','walk_in') COLLATE utf8mb4_unicode_ci DEFAULT 'advance',
  `source` enum('web','qr','whatsapp') COLLATE utf8mb4_unicode_ci DEFAULT 'web',
  `status` enum('pending_payment','confirmed','rescheduled','arrived','completed','cancelled','payment_failed','no_show') COLLATE utf8mb4_unicode_ci DEFAULT 'pending_payment',
  `checked_in_at` datetime DEFAULT NULL,
  `arrival_method` enum('qr','manual','whatsapp') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `total_amount` decimal(10,2) NOT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`booking_id`),
  UNIQUE KEY `slot_id` (`slot_id`),
  KEY `service_id` (`service_id`),
  KEY `voucher_id` (`voucher_id`),
