  KEY `idx_booking_customer_status` (`customer_id`,`status`),
  KEY `idx_booking_service_staff` (`merchant_id`,`service_id`,`staff_id`),
  CONSTRAINT `booking_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`customer_id`),
  CONSTRAINT `booking_ibfk_2` FOREIGN KEY (`merchant_id`) REFERENCES `merchant` (`merchant_id`),
